import importlib; import sys; 
if 'semver' in sys.modules:
    del sys.modules['semver']

import semver
parser = semver.createparser()
args = parser.parse_args(["bump"])
result1 = f"which={args.which}, bump={args.bump}"

try:
    result2 = semver.process(args)
    result = f"{result1}\nprocess succeeded: {result2}"
except Exception as e:
    result = f"{result1}\n{type(e).__name__}: {e}"
result
